export const IN_BROWSER = typeof window !== 'undefined'
export const SUPPORTS_INTERSECTION = IN_BROWSER && 'IntersectionObserver' in window
export const SUPPORTS_TOUCH = IN_BROWSER && ('ontouchstart' in window || window.navigator.maxTouchPoints > 0)
export const SUPPORTS_EYE_DROPPER = IN_BROWSER && 'EyeDropper' in window
/* eslint-disable unused-imports/no-unused-vars */
// Types
import type {
  ComponentInternalInstance,
  ComponentPublicInstance,
  ComputedGetter,
  InjectionKey,
  PropType,
  Ref,
  ToRefs,
  VNode,
  VNodeArrayChildren,
  VNodeChild,
  WatchOptions,
} from 'vue'
// Utilities
import {
  capitalize,
  Comment,
  computed,
  Fragment,
  isVNode,
  reactive,
  readonly,
  shallowRef,
  toRefs,
  unref,
  watchEffect,
} from 'vue'

import { IN_BROWSER } from './globals'

export function getNestedValue(
  obj: any,
  path: (string | number)[],
  fallback?: any,
): any {
  const last = path.length - 1

  if (last < 0)
    return obj === undefined ? fallback : obj

  for (let i = 0; i < last; i++) {
    if (obj == null) {
      return fallback
    }
    obj = obj[path[i]]
  }

  if (obj == null)
    return fallback

  return obj[path[last]] === undefined ? fallback : obj[path[last]]
}

export function deepEqual(a: any, b: any): boolean {
  if (a === b)
    return true

  if (a instanceof Date && b instanceof Date && a.getTime() !== b.getTime()) {
    // If the values are Date, compare them as timestamps
    return false
  }

  if (a !== Object(a) || b !== Object(b)) {
    // If the values aren't objects, they were already checked for equality
    return false
  }

  const props = Object.keys(a)

  if (props.length !== Object.keys(b).length) {
    // Different number of props, don't bother to check
    return false
  }

  return props.every(p => deepEqual(a[p], b[p]))
}

export function getObjectValueByPath(
  obj: any,
  path?: string | null,
  fallback?: any,
): any {
  // credit: http://stackoverflow.com/questions/6491463/accessing-nested-javascript-objects-with-string-key#comment55278413_6491621
  if (obj == null || !path || typeof path !== 'string')
    return fallback
  if (obj[path] !== undefined)
    return obj[path]
  path = path.replace(/\[(\w+)\]/g, '.$1') // convert indexes to properties
  path = path.replace(/^\./, '') // strip a leading dot
  return getNestedValue(obj, path.split('.'), fallback)
}

export type SelectItemKey<T = Record<string, any>> =
  | boolean
  | null
  | undefined // Ignored
  | string // Lookup by key, can use dot notation for nested objects
  | readonly (string | number)[] // Nested lookup by key, each array item is a key in the next level
  | ((item: T, fallback?: any) => any)

export function getPropertyFromItem(
  item: any,
  property: SelectItemKey,
  fallback?: any,
): any {
  if (property === true)
    return item === undefined ? fallback : item

  if (property == null || typeof property === 'boolean')
    return fallback

  if (item !== Object(item)) {
    if (typeof property !== 'function')
      return fallback

    const value = property(item, fallback)

    return typeof value === 'undefined' ? fallback : value
  }

  if (typeof property === 'string')
    return getObjectValueByPath(item, property, fallback)

  if (Array.isArray(property))
    return getNestedValue(item, property, fallback)

  if (typeof property !== 'function')
    return fallback

  const value = property(item, fallback)

  return typeof value === 'undefined' ? fallback : value
}

export function createRange(length: number, start = 0): number[] {
  return Array.from({ length }, (v, k) => start + k)
}

export function getZIndex(el?: Element | null): number {
  if (!el || el.nodeType !== Node.ELEMENT_NODE)
    return 0

  const index = +window.getComputedStyle(el).getPropertyValue('z-index')

  if (!index)
    return getZIndex(el.parentNode as Element)
  return index
}

/**
 * 转换为单位
 * @param str 字符串或数字
 * @param unit 单位
 * @returns 单位字符串
 * @example
 * ```ts
 * const size = convertToUnit('100') // '100px'
 * ```
 */
export function convertToUnit(str: number, unit?: string): string
export function convertToUnit(
  str: string | number | null | undefined,
  unit?: string
): string | undefined
export function convertToUnit(
  str: string | number | null | undefined,
  unit = 'px',
): string | undefined {
  if (str == null || str === '') {
    return undefined
  }
  else if (Number.isNaN(+str!)) {
    return String(str)
  }
  else if (!Number.isFinite(+str!)) {
    return undefined
  }
  else {
    return `${Number(str)}${unit}`
  }
}

/**
 * 是否为纯对象
 * @param obj 对象
 * @returns 是否为纯对象
 * @example
 * ```ts
 * const obj = { a: 1, b: 2 }
 * const isPlain = isPlainObject(obj) // true
 * ```
 */
export function isPlainObject(obj: any): obj is Record<string, any> {
  let proto
  return (
    obj !== null
    && typeof obj === 'object'
    && ((proto = Object.getPrototypeOf(obj)) === Object.prototype
      || proto === null)
  )
}

/**
 * 引用元素
 * @param obj 组件实例或元素
 * @returns 元素
 * @example
 * ```ts
 * const el = refElement(component) // HTMLElement
 * ```
 */
export function refElement(
  obj?: ComponentPublicInstance<any> | HTMLElement,
): HTMLElement | undefined {
  if (obj && '$el' in obj) {
    const el = obj.$el as HTMLElement
    if (el?.nodeType === Node.TEXT_NODE) {
      // Multi-root component, use the first element
      return el.nextElementSibling as HTMLElement
    }
    return el
  }
  return obj as HTMLElement
}

// KeyboardEvent.keyCode aliases
export const keyCodes = Object.freeze({
  enter: 13,
  tab: 9,
  delete: 46,
  esc: 27,
  space: 32,
  up: 38,
  down: 40,
  left: 37,
  right: 39,
  end: 35,
  home: 36,
  del: 46,
  backspace: 8,
  insert: 45,
  pageup: 33,
  pagedown: 34,
  shift: 16,
})

/**
 * 键盘事件别名
 * @example
 * ```ts
 * const keyCodes = keyCodes
 * ```
 */
export const keyValues: Record<string, string> = Object.freeze({
  enter: 'Enter',
  tab: 'Tab',
  delete: 'Delete',
  esc: 'Escape',
  space: 'Space',
  up: 'ArrowUp',
  down: 'ArrowDown',
  left: 'ArrowLeft',
  right: 'ArrowRight',
  end: 'End',
  home: 'Home',
  del: 'Delete',
  backspace: 'Backspace',
  insert: 'Insert',
  pageup: 'PageUp',
  pagedown: 'PageDown',
  shift: 'Shift',
})

export function keys<O extends {}>(o: O) {
  return Object.keys(o) as (keyof O)[]
}

export function has<T extends string>(
  obj: object,
  key: T[],
): obj is Record<T, unknown> {
  return key.every(k => Object.prototype.hasOwnProperty.call(obj, k))
}

type MaybePick<T extends object, U extends Extract<keyof T, string>> =
  Record<string, unknown> extends T ? Partial<Pick<T, U>> : Pick<T, U>

// Array of keys
export function pick<T extends object, U extends Extract<keyof T, string>>(
  obj: T,
  paths: U[],
): MaybePick<T, U> {
  const found: any = {}

  const keys = new Set(Object.keys(obj))
  for (const path of paths) {
    if (keys.has(path)) {
      found[path] = obj[path]
    }
  }

  return found
}

// Array of keys
export function pickWithRest<
  T extends object,
  U extends Extract<keyof T, string>,
  E extends Extract<keyof T, string>,
>(
  obj: T,
  paths: U[],
  exclude?: E[]
): [yes: MaybePick<T, Exclude<U, E>>, no: Omit<T, Exclude<U, E>>]
// Array of keys or RegExp to test keys against
export function pickWithRest<
  T extends object,
  U extends Extract<keyof T, string>,
  E extends Extract<keyof T, string>,
>(
  obj: T,
  paths: (U | RegExp)[],
  exclude?: E[]
): [yes: Partial<T>, no: Partial<T>]
export function pickWithRest<
  T extends object,
  U extends Extract<keyof T, string>,
  E extends Extract<keyof T, string>,
>(
  obj: T,
  paths: (U | RegExp)[],
  exclude?: E[],
): [yes: Partial<T>, no: Partial<T>] {
  const found = Object.create(null)
  const rest = Object.create(null)

  for (const key in obj) {
    if (
      paths.some(path =>
        path instanceof RegExp ? path.test(key) : path === key,
      )
      && !exclude?.some(path => path === key)
    ) {
      found[key] = obj[key]
    }
    else {
      rest[key] = obj[key]
    }
  }

  return [found, rest]
}

export function omit<T extends object, U extends Extract<keyof T, string>>(
  obj: T,
  exclude: U[],
): Omit<T, U> {
  const clone = { ...obj }

  exclude.forEach(prop => delete clone[prop])

  return clone
}

export function only<T extends object, U extends Extract<keyof T, string>>(
  obj: T,
  include: U[],
): Pick<T, U> {
  const clone = {} as T

  include.forEach(prop => (clone[prop] = obj[prop]))

  return clone
}

const onRE = /^on[^a-z]/
export const isOn = (key: string) => onRE.test(key)

const bubblingEvents = [
  'onAfterscriptexecute',
  'onAnimationcancel',
  'onAnimationend',
  'onAnimationiteration',
  'onAnimationstart',
  'onAuxclick',
  'onBeforeinput',
  'onBeforescriptexecute',
  'onChange',
  'onClick',
  'onCompositionend',
  'onCompositionstart',
  'onCompositionupdate',
  'onContextmenu',
  'onCopy',
  'onCut',
  'onDblclick',
  'onFocusin',
  'onFocusout',
  'onFullscreenchange',
  'onFullscreenerror',
  'onGesturechange',
  'onGestureend',
  'onGesturestart',
  'onGotpointercapture',
  'onInput',
  'onKeydown',
  'onKeypress',
  'onKeyup',
  'onLostpointercapture',
  'onMousedown',
  'onMousemove',
  'onMouseout',
  'onMouseover',
  'onMouseup',
  'onMousewheel',
  'onPaste',
  'onPointercancel',
  'onPointerdown',
  'onPointerenter',
  'onPointerleave',
  'onPointermove',
  'onPointerout',
  'onPointerover',
  'onPointerup',
  'onReset',
  'onSelect',
  'onSubmit',
  'onTouchcancel',
  'onTouchend',
  'onTouchmove',
  'onTouchstart',
  'onTransitioncancel',
  'onTransitionend',
  'onTransitionrun',
  'onTransitionstart',
  'onWheel',
]

const compositionIgnoreKeys = [
  'ArrowUp',
  'ArrowDown',
  'ArrowRight',
  'ArrowLeft',
  'Enter',
  'Escape',
  'Tab',
  ' ',
]

export function isComposingIgnoreKey(e: KeyboardEvent): boolean {
  return e.isComposing && compositionIgnoreKeys.includes(e.key)
}

/**
 * Filter attributes that should be applied to
 * the root element of an input component. Remaining
 * attributes should be passed to the <input> element inside.
 */
export function filterInputAttrs(attrs: Record<string, unknown>) {
  const [events, props] = pickWithRest(attrs, [onRE])
  const inputEvents = omit(events, bubblingEvents)
  const [rootAttrs, inputAttrs] = pickWithRest(props, [
    'class',
    'style',
    'id',
    /^data-/,
  ])
  Object.assign(rootAttrs, events)
  Object.assign(inputAttrs, inputEvents)
  return [rootAttrs, inputAttrs]
}

/**
 * Returns the set difference of B and A, i.e. the set of elements in B but not in A
 */
export function arrayDiff(a: any[], b: any[]): any[] {
  const diff: any[] = []
  for (let i = 0; i < b.length; i++) {
    if (!a.includes(b[i]))
      diff.push(b[i])
  }
  return diff
}

type IfAny<T, Y, N> = 0 extends 1 & T ? Y : N
export function wrapInArray<T>(
  v: T | null | undefined,
): T extends readonly any[] ? IfAny<T, T[], T> : NonNullable<T>[] {
  return v == null ? [] : Array.isArray(v) ? (v as any) : [v]
}

export function defaultFilter(value: any, search: string | null, _item: any) {
  return (
    value != null
    && search != null
    && typeof value !== 'boolean'
    && value.toString().toLocaleLowerCase().includes(search.toLocaleLowerCase())
  )
}

export function debounce(fn: Function, delay: MaybeRef<number>) {
  let timeoutId = 0 as any
  const wrap = (...args: any[]) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => fn(...args), unref(delay))
  }
  wrap.clear = () => {
    clearTimeout(timeoutId)
  }
  wrap.immediate = fn
  return wrap
}

export function throttle<T extends (...args: any[]) => any>(
  fn: T,
  limit: number,
) {
  let throttling = false
  return (...args: Parameters<T>): void | ReturnType<T> => {
    if (!throttling) {
      throttling = true
      setTimeout(() => (throttling = false), limit)
      return fn(...args)
    }
  }
}

export function clamp(value: number, min = 0, max = 1) {
  return Math.max(min, Math.min(max, value))
}

export function getDecimals(value: number) {
  const trimmedStr = value.toString().trim()
  return trimmedStr.includes('.')
    ? trimmedStr.length - trimmedStr.indexOf('.') - 1
    : 0
}

export function padEnd(str: string, length: number, char = '0') {
  return str + char.repeat(Math.max(0, length - str.length))
}

export function padStart(str: string, length: number, char = '0') {
  return char.repeat(Math.max(0, length - str.length)) + str
}

export function chunk(str: string, size = 1) {
  const chunked: string[] = []
  let index = 0
  while (index < str.length) {
    chunked.push(str.substr(index, size))
    index += size
  }
  return chunked
}

export function chunkArray(array: any[], size = 1) {
  return Array.from({ length: Math.ceil(array.length / size) }, (v, i) =>
    array.slice(i * size, i * size + size))
}

export function humanReadableFileSize(
  bytes: number,
  base: 1000 | 1024 = 1000,
): string {
  if (bytes < base) {
    return `${bytes} B`
  }

  const prefix = base === 1024 ? ['Ki', 'Mi', 'Gi'] : ['k', 'M', 'G']
  let unit = -1
  while (Math.abs(bytes) >= base && unit < prefix.length - 1) {
    bytes /= base
    ++unit
  }
  return `${bytes.toFixed(1)} ${prefix[unit]}B`
}

/**
 * 深度合并对象
 * 作用：将源对象和目标对象进行深度合并
 *
 * @param source - 源对象
 * @param target - 目标对象
 * @param arrayFn - 数组合并函数（可选）
 * @returns 合并后的对象
 *
 * 核心功能：
 * 1. 递归合并对象
 * 2. 支持数组合并
 * 3. 支持深度合并
 * 4. 支持数组合并函数
 */

export function mergeDeep(
  source: Record<string, any> = {},
  target: Record<string, any> = {},
  arrayFn?: (a: unknown[], b: unknown[]) => unknown[],
) {
  const out: Record<string, any> = {}

  for (const key in source) {
    out[key] = source[key]
  }

  for (const key in target) {
    const sourceProperty = source[key]
    const targetProperty = target[key]

    // Only continue deep merging if
    // both properties are plain objects
    if (isPlainObject(sourceProperty) && isPlainObject(targetProperty)) {
      out[key] = mergeDeep(sourceProperty, targetProperty, arrayFn)

      continue
    }

    if (
      arrayFn
      && Array.isArray(sourceProperty)
      && Array.isArray(targetProperty)
    ) {
      out[key] = arrayFn(sourceProperty, targetProperty)

      continue
    }

    out[key] = targetProperty
  }

  return out
}

/**
 * 扁平化片段
 * 作用：将片段中的子节点扁平化
 *
 * @param nodes - 片段节点
 * @returns 扁平化后的节点
 *
 * 核心功能：
 * 1. 递归扁平化片段中的子节点
 * 2. 支持片段节点
 * 3. 支持非片段节点
 * @example
 * ```ts
 * const nodes = flattenFragments([
 *   h('div', 'Hello'),
 *   h('div', 'World'),
 * ])
 * ```
 */
export function flattenFragments(nodes: VNode[]): VNode[] {
  return nodes
    .map((node) => {
      if (node.type === Fragment) {
        return flattenFragments(node.children as VNode[])
      }
      else {
        return node
      }
    })
    .flat()
}

/**
 * 将字符串转换为 kebab-case 格式
 * @param str - 要转换的字符串，默认为空字符串
 * @returns 转换后的 kebab-case 字符串
 *
 * 核心功能：
 * 1. 将字符串转换为 kebab-case 格式
 * 2. 支持空字符串
 * 3. 支持缓存转换结果
 * @example
 * ```ts
 * const kebab = toKebabCase('Hello World') // 'hello-world'
 * ```
 */
export function toKebabCase(str = '') {
  // 如果缓存中已经存在该字符串的转换结果，则直接返回缓存中的结果
  if (toKebabCase.cache.has(str))
    return toKebabCase.cache.get(str)!
  // 使用正则表达式将字符串中的非字母字符替换为连字符，并将大写字母转换为小写字母
  const kebab = str
    .replace(/[^a-z]/gi, '-')
    .replace(/\B([A-Z])/g, '-$1')
    .toLowerCase()
  // 将转换结果存储到缓存中
  toKebabCase.cache.set(str, kebab)
  // 返回转换后的 kebab-case 字符串
  return kebab
}
// 创建一个 Map 对象，用于缓存转换结果
toKebabCase.cache = new Map<string, string>()

export type MaybeRef<T> = T | Ref<T>

/**
 * 查找具有提供者的子组件
 * 作用：查找具有提供者的子组件
 *
 * @param key - 注入的键
 * @param vnode - 虚拟节点
 * @returns 具有提供者的子组件
 *
 * 核心功能：
 * 1. 查找具有提供者的子组件
 * 2. 支持虚拟节点
 * 3. 支持数组虚拟节点
 * 4. 支持 suspense 虚拟节点
 * 5. 支持组件虚拟节点
 * @example
 * ```ts
 * const children = findChildrenWithProvide(Symbol('provide'), vnode)
 * ```
 */
export function findChildrenWithProvide(
  key: InjectionKey<any> | symbol,
  vnode?: VNodeChild,
): ComponentInternalInstance[] {
  if (!vnode || typeof vnode !== 'object')
    return []

  if (Array.isArray(vnode)) {
    return vnode.map(child => findChildrenWithProvide(key, child)).flat(1)
  }
  else if (vnode.suspense) {
    return findChildrenWithProvide(key, vnode.ssContent!)
  }
  else if (Array.isArray(vnode.children)) {
    return vnode.children
      .map(child => findChildrenWithProvide(key, child))
      .flat(1)
  }
  else if (vnode.component) {
    if (
      Object.getOwnPropertySymbols(vnode.component.provides).includes(
        key as symbol,
      )
    ) {
      return [vnode.component]
    }
    else if (vnode.component.subTree) {
      return findChildrenWithProvide(key, vnode.component.subTree).flat(1)
    }
  }

  return []
}

/**
 * 循环缓冲区
 * 作用：循环缓冲区
 *
 * @param size - 缓冲区大小
 * @returns 循环缓冲区
 */
export class CircularBuffer<T = never> {
  readonly #arr: Array<T> = []
  #pointer = 0

  constructor(public readonly size: number) {}

  push(val: T) {
    this.#arr[this.#pointer] = val
    this.#pointer = (this.#pointer + 1) % this.size
  }

  values(): T[] {
    return this.#arr
      .slice(this.#pointer)
      .concat(this.#arr.slice(0, this.#pointer))
  }
}

export type UnionToIntersection<U> = (
  U extends any ? (k: U) => void : never
) extends (k: infer I) => void
  ? I
  : never

export function getEventCoordinates(e: MouseEvent | TouchEvent) {
  if ('touches' in e) {
    return { clientX: e.touches[0].clientX, clientY: e.touches[0].clientY }
  }

  return { clientX: e.clientX, clientY: e.clientY }
}

// Only allow a single return type
type NotAUnion<T> = [T] extends [infer U] ? _NotAUnion<U, U> : never
type _NotAUnion<T, U> = U extends any
  ? [T] extends [U]
      ? unknown
      : never
  : never

/**
 * Convert a computed ref to a record of refs.
 * The getter function must always return an object with the same keys.
 */
export function destructComputed<T extends object>(
  getter: ComputedGetter<T & NotAUnion<T>>
): ToRefs<T>
/**
 * 将计算的 ref 转换为 refs 的记录
 * @param getter 计算的 getter 函数
 * @returns refs 的记录
 * @example
 * ```ts
 * const { a, b } = destructComputed(() => ({ a: 1, b: 2 }))
 * ```
 */
export function destructComputed<T extends object>(getter: ComputedGetter<T>) {
  const refs = reactive({}) as T
  const base = computed(getter)
  watchEffect(
    () => {
      for (const key in base.value) {
        refs[key] = base.value[key]
      }
    },
    { flush: 'sync' },
  )
  return toRefs(refs)
}

/** Array.includes but value can be any type */
export function includes(arr: readonly any[], val: any) {
  return arr.includes(val)
}

export function eventName(propName: string) {
  return propName[2].toLowerCase() + propName.slice(3)
}

export type EventProp<T extends any[] = any[], F = (...args: T) => void> = F
export function EventProp<T extends any[] = any[]>() {
  return [Function, Array] as PropType<EventProp<T>>
}

export function hasEvent(props: Record<string, any>, name: string) {
  name = `on${capitalize(name)}`
  return !!(
    props[name]
    || props[`${name}Once`]
    || props[`${name}Capture`]
    || props[`${name}OnceCapture`]
    || props[`${name}CaptureOnce`]
  )
}

export function callEvent<T extends any[]>(
  handler: EventProp<T> | undefined,
  ...args: T
) {
  if (Array.isArray(handler)) {
    for (const h of handler) {
      h(...args)
    }
  }
  else if (typeof handler === 'function') {
    handler(...args)
  }
}

export function focusableChildren(el: Element, filterByTabIndex = true) {
  const targets = [
    'button',
    '[href]',
    'input:not([type="hidden"])',
    'select',
    'textarea',
    '[tabindex]',
  ]
    .map(
      s =>
        `${s}${filterByTabIndex ? ':not([tabindex="-1"])' : ''}:not([disabled])`,
    )
    .join(', ')
  return [...el.querySelectorAll(targets)] as HTMLElement[]
}

export function getNextElement(
  elements: HTMLElement[],
  location?: 'next' | 'prev',
  condition?: (el: HTMLElement) => boolean,
) {
  let _el
  let idx = elements.indexOf(document.activeElement as HTMLElement)
  const inc = location === 'next' ? 1 : -1
  do {
    idx += inc
    _el = elements[idx]
  } while (
    (!_el || _el.offsetParent == null || !(condition?.(_el) ?? true))
    && idx < elements.length
    && idx >= 0
  )
  return _el
}

export function focusChild(
  el: Element,
  location?: 'next' | 'prev' | 'first' | 'last' | number,
) {
  const focusable = focusableChildren(el)

  if (!location) {
    if (el === document.activeElement || !el.contains(document.activeElement)) {
      focusable[0]?.focus()
    }
  }
  else if (location === 'first') {
    focusable[0]?.focus()
  }
  else if (location === 'last') {
    focusable.at(-1)?.focus()
  }
  else if (typeof location === 'number') {
    focusable[location]?.focus()
  }
  else {
    const _el = getNextElement(focusable, location)
    if (_el)
      _el.focus()
    else focusChild(el, location === 'next' ? 'first' : 'last')
  }
}

