export function noop() {}

/** Returns null if the selector is not supported or we can't check */
export function matchesSelector(
  el: Element | undefined,
  selector: string,
): boolean | null {
  const supportsSelector
    = IN_BROWSER
      && typeof CSS !== 'undefined'
      && typeof CSS.supports !== 'undefined'
      && CSS.supports(`selector(${selector})`)

  if (!supportsSelector)
    return null

  try {
    return !!el && el.matches(selector)
  }
  catch (_) {
    return null
  }
}

export function ensureValidVNode(
  vnodes: VNodeArrayChildren,
): VNodeArrayChildren | null {
  return vnodes.some((child) => {
    if (!isVNode(child))
      return true
    if (child.type === Comment)
      return false
    return (
      child.type !== Fragment
      || ensureValidVNode(child.children as VNodeArrayChildren)
    )
  })
    ? vnodes
    : null
}

export function defer(timeout: number, cb: () => void) {
  if (!IN_BROWSER || timeout === 0) {
    cb()

    return () => {}
  }

  const timeoutId = window.setTimeout(cb, timeout)

  return () => window.clearTimeout(timeoutId)
}

export function eagerComputed<T>(
  fn: () => T,
  options?: WatchOptions,
): Readonly<Ref<T>> {
  const result = shallowRef()

  watchEffect(
    () => {
      result.value = fn()
    },
    {
      flush: 'sync',
      ...options,
    },
  )

  return readonly(result)
}

export function isClickInsideElement(
  event: MouseEvent,
  targetDiv: HTMLElement,
) {
  const mouseX = event.clientX
  const mouseY = event.clientY

  const divRect = targetDiv.getBoundingClientRect()
  const divLeft = divRect.left
  const divTop = divRect.top
  const divRight = divRect.right
  const divBottom = divRect.bottom

  return (
    mouseX >= divLeft
    && mouseX <= divRight
    && mouseY >= divTop
    && mouseY <= divBottom
  )
}

export interface TemplateRef {
  (target: Element | ComponentPublicInstance | null): void
  value: HTMLElement | ComponentPublicInstance | null | undefined
  readonly el: HTMLElement | undefined
}
export function templateRef() {
  const el = shallowRef<HTMLElement | ComponentPublicInstance | null>()
  const fn = (target: HTMLElement | ComponentPublicInstance | null) => {
    el.value = target
  }
  Object.defineProperty(fn, 'value', {
    enumerable: true,
    get: () => el.value,
    set: val => (el.value = val),
  })
  Object.defineProperty(fn, 'el', {
    enumerable: true,
    get: () => refElement(el.value),
  })

  return fn as TemplateRef
}

export function checkPrintable(e: KeyboardEvent) {
  const isPrintableChar = e.key.length === 1
  const noModifier = !e.ctrlKey && !e.metaKey && !e.altKey
  return isPrintableChar && noModifier
}
// Utilities
import { includes } from './helpers'

const block = ['top', 'bottom'] as const
const inline = ['start', 'end', 'left', 'right'] as const
type Tblock = (typeof block)[number]
type Tinline = (typeof inline)[number]
export type Anchor =
  | Tblock
  | Tinline
  | 'center'
  | 'center center'
  | `${Tblock} ${Tinline | 'center'}`
  | `${Tinline} ${Tblock | 'center'}`
export type ParsedAnchor =
  | { side: 'center', align: 'center' }
  | { side: Tblock, align: 'left' | 'right' | 'center' }
  | { side: 'left' | 'right', align: Tblock | 'center' }

/** Parse a raw anchor string into an object */
/**
 * 解析锚点字符串并返回一个包含 side 和 align 属性的对象
 * @param anchor - 锚点字符串，可以是 'top'、'bottom'、'start'、'end'、'left'、'right'、'center' 或它们的组合
 * @param isRtl - 是否为从右到左的布局
 * @returns 一个包含 side 和 align 属性的对象
 */
export function parseAnchor(anchor: Anchor, isRtl: boolean) {
  // 将锚点字符串按空格分割成数组，并将第一个元素赋值给 side，第二个元素赋值给 align
  let [side, align] = anchor.split(' ') as [
    Tblock | Tinline | 'center',
    Tblock | Tinline | 'center' | undefined,
  ]
  // 如果 align 不存在，则根据 side 的值设置默认的 align
  if (!align) {
    align = includes(block, side)
      ? 'start'
      : includes(inline, side)
        ? 'top'
        : 'center'
  }

  // 返回一个包含 side 和 align 属性的对象，side 和 align 的值通过 toPhysical 函数转换为物理方向
  return {
    side: toPhysical(side, isRtl),
    align: toPhysical(align, isRtl),
  } as ParsedAnchor
}

/**
 * 将逻辑方向转换为物理方向
 * @param str - 逻辑方向字符串，可以是 'center'、'top'、'bottom'、'start'、'end'、'left' 或 'right'
 * @param isRtl - 是否为从右到左的布局
 * @returns 物理方向字符串
 */
export function toPhysical(str: 'center' | Tblock | Tinline, isRtl: boolean) {
  // 如果逻辑方向是 'start'，则根据 isRtl 的值返回 'right' 或 'left'
  if (str === 'start')
    return isRtl ? 'right' : 'left'
  // 如果逻辑方向是 'end'，则根据 isRtl 的值返回 'left' 或 'right'
  if (str === 'end')
    return isRtl ? 'left' : 'right'
  // 如果逻辑方向是 'center'、'top'、'bottom'、'left' 或 'right'，则直接返回该字符串
  return str
}

/**
 * 翻转锚点的侧方向
 * @param anchor - 包含 side 和 align 属性的对象
 * @returns 一个新的对象，其中 side 属性被翻转，align 属性保持不变
 */
export function flipSide(anchor: ParsedAnchor) {
  // 使用对象字面量和计算属性名来翻转 side 属性的值
  return {
    side: {
      center: 'center',
      top: 'bottom',
      bottom: 'top',
      left: 'right',
      right: 'left',
    }[anchor.side],
    // align 属性保持不变
    align: anchor.align,
  } as ParsedAnchor
}

export function flipAlign(anchor: ParsedAnchor) {
  return {
    side: anchor.side,
    align: {
      center: 'center',
      top: 'bottom',
      bottom: 'top',
      left: 'right',
      right: 'left',
    }[anchor.align],
  } as ParsedAnchor
}

export function flipCorner(anchor: ParsedAnchor) {
  return {
    side: anchor.align,
    align: anchor.side,
  } as ParsedAnchor
}

export function getAxis(anchor: ParsedAnchor) {
  return includes(block, anchor.side) ? 'y' : 'x'
}
